/** Admin-only Auto Code Override console — search any auto-generated reference code and override it. */
import { useEffect, useState } from "react";
import { api, apiErrorMessage } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Loader2, KeyRound, Search, ShieldCheck } from "lucide-react";

export default function CodeOverride() {
  const [registry, setRegistry] = useState([]);
  const [resource, setResource] = useState("");
  const [q, setQ] = useState("");
  const [rows, setRows] = useState([]);
  const [searching, setSearching] = useState(false);
  const [selected, setSelected] = useState(null);
  const [newCode, setNewCode] = useState("");
  const [applying, setApplying] = useState(false);

  useEffect(() => {
    api.get("/admin/code-override/registry").then((r) => setRegistry(r.data || [])).catch((e) => toast.error(apiErrorMessage(e)));
  }, []);

  useEffect(() => {
    if (!resource) { setRows([]); setSelected(null); return; }
    setSearching(true);
    const t = setTimeout(() => {
      api.get("/admin/code-override/records", { params: { resource, q: q || undefined } })
        .then((r) => setRows(r.data || []))
        .catch((e) => toast.error(apiErrorMessage(e)))
        .finally(() => setSearching(false));
    }, 300);
    return () => clearTimeout(t);
  }, [resource, q]);

  const apply = async () => {
    setApplying(true);
    try {
      const r = await api.post("/admin/code-override", { resource, record_id: selected.id, new_code: newCode });
      const prop = r.data.propagated_total || 0;
      toast.success(`Code changed: ${r.data.old_code} → ${r.data.new_code}${prop ? ` · updated in ${prop} linked record(s)` : ""}`);
      setSelected(null); setNewCode("");
      const rr = await api.get("/admin/code-override/records", { params: { resource, q: q || undefined } });
      setRows(rr.data || []);
    } catch (e) { toast.error(apiErrorMessage(e, "Override failed")); }
    finally { setApplying(false); }
  };

  return (
    <div className="p-6 max-w-5xl" data-testid="code-override-page">
      <div className="flex items-center gap-2 mb-1">
        <ShieldCheck className="h-5 w-5 text-blue-700" />
        <h1 className="font-display text-xl font-bold">Auto Code Override</h1>
        <span className="text-[10px] uppercase tracking-wider bg-blue-100 text-blue-800 rounded-full px-2 py-0.5">Super Admin only</span>
      </div>
      <p className="text-sm text-slate-500 mb-5">
        Codes are always auto-generated by default. Use this console to manually override any generated reference code.
        The new code propagates automatically to every linked record across the ERP (transactions, references, dashboards).
        Uniqueness is enforced; every override is recorded in the audit log with propagation details.
      </p>

      <div className="grid md:grid-cols-2 gap-4 mb-4">
        <div>
          <Label className="text-xs uppercase tracking-wider">Module / Code Type</Label>
          <select value={resource} onChange={(e) => { setResource(e.target.value); setSelected(null); }}
            className="h-9 w-full rounded-sm border border-input bg-background px-2 text-sm mt-1" data-testid="code-override-resource">
            <option value="">— select module —</option>
            {registry.map((r) => <option key={r.key} value={r.key}>{r.label}</option>)}
          </select>
        </div>
        <div>
          <Label className="text-xs uppercase tracking-wider">Search (code or name)</Label>
          <div className="relative mt-1">
            <Search className="h-3.5 w-3.5 absolute left-2.5 top-3 text-slate-400" />
            <Input value={q} onChange={(e) => setQ(e.target.value)} className="h-9 pl-8 rounded-sm" placeholder="e.g. QTN-2026 or client name" data-testid="code-override-search" />
          </div>
        </div>
      </div>

      {resource && (
        <div className="grid md:grid-cols-2 gap-4">
          <div className="border rounded-sm overflow-hidden">
            <div className="bg-slate-50 px-3 py-2 text-xs uppercase tracking-wider text-slate-500 flex justify-between">
              <span>Records</span>{searching && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
            </div>
            <div className="max-h-96 overflow-y-auto divide-y">
              {rows.length === 0 && !searching && <div className="p-4 text-sm text-slate-500">No records</div>}
              {rows.map((r) => (
                <button key={r.id} onClick={() => { setSelected(r); setNewCode(r.code || ""); }}
                  data-testid={`code-override-row-${r.code}`}
                  className={`w-full text-left px-3 py-2 hover:bg-blue-50 ${selected?.id === r.id ? "bg-blue-50 border-l-2 border-blue-600" : ""}`}>
                  <div className="font-mono-data text-sm font-semibold">{r.code || "—"}</div>
                  <div className="text-xs text-slate-500 truncate">{r.display}</div>
                </button>
              ))}
            </div>
          </div>

          <div className="border rounded-sm p-4 h-fit">
            {!selected ? (
              <div className="text-sm text-slate-500 py-8 text-center"><KeyRound className="h-6 w-6 mx-auto mb-2 text-slate-300" />Select a record to override its code</div>
            ) : (
              <div className="space-y-3">
                <div>
                  <div className="text-[10px] uppercase tracking-wider text-slate-500">Current Code</div>
                  <div className="font-mono-data text-lg font-bold">{selected.code || "—"}</div>
                  <div className="text-xs text-slate-500">{selected.display}</div>
                </div>
                <div>
                  <Label className="text-xs uppercase tracking-wider">New Code</Label>
                  <Input value={newCode} onChange={(e) => setNewCode(e.target.value)} className="h-9 rounded-sm mt-1 font-mono-data" data-testid="code-override-new-code" />
                </div>
                <div className="flex gap-2">
                  <Button onClick={apply} disabled={applying || !newCode.trim() || newCode.trim() === selected.code}
                    className="rounded-sm" data-testid="code-override-apply">
                    {applying ? <Loader2 className="h-4 w-4 mr-1.5 animate-spin" /> : <KeyRound className="h-4 w-4 mr-1.5" />}
                    Apply Override
                  </Button>
                  <Button variant="outline" className="rounded-sm" onClick={() => { setSelected(null); setNewCode(""); }}>Cancel</Button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
